def to_chinese_numeral(n):
    if n is None:
        return None

    def int_to_chinese(num):
        if num == 0:
            return '零'
        elif num < 10:
            return DIGIT_TO_CHINESE[num]
        elif num < 20:
            return '十' + int_to_chinese(num - 10)
        elif num < 100:
