            return DIGIT_TO_CHINESE[tens] + '十' + (int_to_chinese(ones) if ones != 0 else '')
        elif num < 1000:
            hundreds, rest = divmod(num, 100)
            return int_to_chinese(hundreds) + '百' + (int_to_chinese(rest) if rest != 0 else '')
        elif num < 10000:
            thousands, rest = divmod(num, 1000)
            return int_to_chinese(thousands) + '千' + (int_to_chinese(rest) if rest != 0 else '')

    def decimal_to_chinese(num):
        parts = str(num).split('.')
        if len(parts) == 1:
            return int_to_chinese(int(parts[0]))
        else:
            whole, decimal = parts
            return int_to_chinese(int(whole)) + '点' + decimal_to_chinese(decimal)

