def to_chinese_numeral(n):
    chinese_numerals = {
        0: '零', 1: '一', 2: '二', 3: '三', 4: '四', 5: '五', 6: '六', 7: '七', 8: '八', 9: '九',
        10: '十', 100: '百', 1000: '千', 10000: '万'
    }
    is_negative = n < 0
    n = abs(n)
    integer_part = int(n)
    decimal_part = int((n - integer_part) * 10000)  # Round to 4 decimal places

    def convert_part(part, multiplier):
        if part == 0:
            return chinese_numerals[part]
        result = ''
        for i, digit in enumerate(str(part)[::-1]):
            if digit != '0' or (i == 0 and part != 1) or (i == 1 and part == 10):
                result = chinese_numerals[int(digit)] + (chinese_numerals[multiplier] if multiplier else '') + result
            else:
                result = chinese_numerals[0] + (chinese_numerals[multiplier] if multiplier else '') + result
        return result

    integer_result = convert_part(integer_part, None)
    decimal_result = convert_part(decimal_part, None)

    if is_negative:
        integer_result = '负' + integer_result

    if decimal_result:
        integer_result += '点' + decimal_result

    return integer_result
